function openDocumentStore(){return new Promise((resolve,reject)=>{const request=indexedDB.open('routecrew-driver-documents',1);request.onupgradeneeded=()=>{const db=request.result;if(!db.objectStoreNames.contains('documents'))db.createObjectStore('documents',{keyPath:'id'})};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}
async function saveDocumentBlob(record){const db=await openDocumentStore();return new Promise((resolve,reject)=>{const tx=db.transaction('documents','readwrite');tx.objectStore('documents').put(record);tx.oncomplete=()=>{db.close();resolve()};tx.onerror=()=>reject(tx.error)})}
async function getDocumentBlob(id){const db=await openDocumentStore();return new Promise((resolve,reject)=>{const tx=db.transaction('documents','readonly');const request=tx.objectStore('documents').get(id);request.onsuccess=()=>{db.close();resolve(request.result||null)};request.onerror=()=>reject(request.error)})}
